content.solution_code:
class Ingredient {
    constructor(name, potency) {
        this.name = name;
        this.potency = potency;
    }
}

class Potion {
    constructor(name, totalPotency) {
        this.name = name;
        this.totalPotency = totalPotency;
    }

    getDescription() {
        return `${this.name} (Potency: ${this.totalPotency})`;
    }
}

class PotionBrewer {
    brewPotion(ingredients) {
        let totalPotency = 0;
        let validIngredientsCount = 0;

        // Defensive check for the ingredients array itself
        if (!Array.isArray(ingredients) || ingredients.length === 0) {
            return new Potion("Failed Brew (No Ingredients Provided)", 0);
        }

        for (const ingredient of ingredients) {
            // Defensive checks for individual ingredients
            if (ingredient === null || typeof ingredient !== 'object' || 
                !ingredient.name || typeof ingredient.name !== 'string' ||
                typeof ingredient.potency !== 'number' || isNaN(ingredient.potency)) {
                console.warn("Skipping invalid or malformed ingredient.");
                continue;
            }

            totalPotency += ingredient.potency;
            validIngredientsCount++;
        }

        if (validIngredientsCount === 0) {
            return new Potion("Failed Brew (No Valid Ingredients Processed)", 0);
        }

        const potionName = `Concoction of ${validIngredientsCount} Elements`;
        return new Potion(potionName, totalPotency);
    }
}

